-- Gold Query
SELECT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t1.height > 180 GROUP BY t1.id ORDER BY CAST(SUM(t2.heading_accuracy) AS REAL) / COUNT(t2."player_fifa_api_id") DESC, t1.player_name NULLS LAST LIMIT 10;

/*
Gold Result:
('Matthew Foster',)
*/

-- Prediction Query
SELECT "player"."player_name" FROM "player" INNER JOIN "player_attributes" ON "player"."player_fifa_api_id" = "player_attributes"."player_fifa_api_id" WHERE "player"."height" > 180 GROUP BY "player"."player_name" ORDER BY AVG("player_attributes"."heading_accuracy") DESC, "player"."player_name" NULLS LAST LIMIT 10;

